cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');
// Check all order_id formats
const samples = db.prepare(\"SELECT order_id, customer_id, source_skill FROM orders WHERE source_skill='tau2Retail' LIMIT 5\").all();
console.log('Sample tau2Retail orders:', JSON.stringify(samples, null, 2));
// Check for any order with 7113
const allOrders = db.prepare(\"SELECT order_id FROM orders\").all();
const match = allOrders.filter(o => o.order_id.includes('7113'));
console.log('Any order with 7113:', JSON.stringify(match));
"

